export const title = "Will a Standing Desk Converter Fit Your Narrow Desk?";
export const metaTitle = "Will a Desk Converter Fit Your Narrow Desk?";
export const metaDescription = "Check a converter’s supported base, lift path, seated height, keyboard tray, combined load, and cable travel before buying.";
